<?php
$draftSql="SELECT r.id,r.kind,r.module_code,r.module_name,r.programme,r.academic_year,r.study_year,r.semester,r.updated_at FROM academic_records r WHERE (r.status='Draft' OR (r.kind='attendance' AND EXISTS(SELECT 1 FROM attendance_drafts d WHERE d.record_id=r.id)))";
$draftItems=all($draftSql.(acAdmin($user)?'':' AND r.owner_id=?').' ORDER BY r.updated_at DESC,r.id DESC',acAdmin($user)?[]:[$user['id']]);$draftPages=max(1,(int)ceil(count($draftItems)/6));$draftPage=min($draftPages,max(1,(int)($_GET['draft_page']??1)));
?>
<section class="draft-hub" id="saved-drafts"><div class="draft-hub-heading"><div><span class="draft-eyebrow">PICK UP WHERE YOU LEFT OFF</span><h2><?=acAdmin($user)?'Saved drafts':'Your saved drafts'?></h2><p>Your work is saved. Open a draft to add records, review and submit.</p></div><span class="draft-total"><?=count($draftItems)?> <small>draft<?=count($draftItems)===1?'':'s'?></small></span></div>
<div class="draft-card-grid"><?php foreach(array_slice($draftItems,($draftPage-1)*6,6) as $item):?><article class="saved-draft-card"><div class="draft-card-top"><span><?=e(acKinds()[$item['kind']])?></span><b>Not submitted</b></div><h3><?=e($item['module_code'])?></h3><p class="draft-module-name"><?=e($item['module_name'])?></p><p class="draft-cohort"><?=e($item['programme'])?><br><?=e($item['academic_year'].' · Year '.$item['study_year'].' · Semester '.$item['semester'])?></p><p class="draft-updated">Last saved <?=e($item['updated_at'])?></p><a class="draft-continue" href="?page=<?=$item['kind']==='attendance'?'sa_record':'ac_record'?>&id=<?=$item['id']?><?=$item['kind']==='attendance'?'#enter-attendance':''?>">Continue draft <span aria-hidden="true">→</span></a></article><?php endforeach;?></div>
<?php if(!$draftItems):?><p class="draft-empty">No unfinished drafts. Create a module below to get started.</p><?php endif;if($draftPages>1):?><nav class="draft-pages" aria-label="Draft pages">Page <?=$draftPage?> of <?=$draftPages?> <?php foreach(['Previous'=>$draftPage-1,'Next'=>$draftPage+1] as $label=>$target)if($target>=1&&$target<=$draftPages):?><a href="?page=ac_home&draft_page=<?=$target?>#saved-drafts"><?=e($label)?></a><?php endif;?></nav><?php endif;?></section>
